import{_ as a}from"./chunks/reimport.C-npY4qk.js";import{_ as s,o as i,c as r,a5 as t}from"./chunks/framework.BEZBAInb.js";const m=JSON.parse('{"title":"KonadoScript","description":"","frontmatter":{"title":"KonadoScript","order":1},"headers":[],"relativePath":"en/2.4/tutorial/script/konado-script.md","filePath":"en/2.4/tutorial/script/konado-script.md","lastUpdated":1788455378000}'),o={name:"en/2.4/tutorial/script/konado-script.md"};function n(l,e,p,c,d,u){return i(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="konadoscript" tabindex="-1">KonadoScript <a class="header-anchor" href="#konadoscript" aria-label="Permalink to &quot;KonadoScript&quot;">​</a></h1><p>KonadoScript is an authoring language tailored for visual novels. Its file extension is <code>.ks</code>.</p><p>You can think of it as a more powerful and more structured &quot;novel script&quot;: developers can control story dialogue, character portraits, background switching, music and sound effects, story branches, and choices without writing complex code.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><p>The core design philosophy of KonadoScript is to separate <strong>story content</strong> from <strong>program logic</strong>:</p><ul><li>Writers focus on narrative content without needing programming knowledge</li><li>Programmers focus on engine development without intervening in story creation</li><li>Resource management (images and audio) uses identifiers and is decoupled from scripts</li><li>Modular instruction set, easy to extend with new features</li><li>Compatible with version control systems such as Git</li><li>Text format is naturally cross-platform</li><li>Resource references are platform-independent</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="_1-saving-after-a-parse-failure-does-not-trigger-reparsing" tabindex="-1">1. Saving after a parse failure does not trigger reparsing <a class="header-anchor" href="#_1-saving-after-a-parse-failure-does-not-trigger-reparsing" aria-label="Permalink to &quot;1. Saving after a parse failure does not trigger reparsing&quot;">​</a></h3><p>The console will show an error message, but saving the file will not automatically trigger reparsing. This happens because reimport was not triggered successfully.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Line 5 content: a1ctor show Kona normal at 2 5 scale 0.3</span></span>
<span class="line"><span>  ERROR: core/variant/variant_utility.cpp:1024 - Error: res://sample/demo/demo_01.ks [Line: 5] Parse failed: unrecognized syntax, parsing stopped: a1ctor show Kona normal at 2 5 scale 0.3 </span></span>
<span class="line"><span>  ERROR: Failed to process scripts</span></span>
<span class="line"><span>  ERROR: Error importing &#39;res://sample/demo/demo_01.ks&#39;.</span></span>
<span class="line"><span>  ERROR: Failed loading resource: res://sample/demo/demo_01.ks.</span></span></code></pre></div><p>Find the corresponding script file, right-click it, and select reimport.</p><p><img src="`+a+'" alt="Reimport script"></p><h3 id="_2-script-file-encoding-issues" tabindex="-1">2. Script file encoding issues <a class="header-anchor" href="#_2-script-file-encoding-issues" aria-label="Permalink to &quot;2. Script file encoding issues&quot;">​</a></h3><p>Make sure the script file is encoded as UTF-8, otherwise garbled text may appear. Script files created by default use UTF-8 encoding.</p>',14)])])}const f=s(o,[["render",n]]);export{m as __pageData,f as default};
